{"t":"assume","id":"approval-rule","text":"Auto-approve only exact three-way matches under threshold","alt":"All invoices require manual approval regardless of match"}
{"t":"ask","id":"volume","text":"How many supplier invoices do you expect to process per day?"}
{"t":"ask","id":"success","text":"What defines a successful match, and what is today's manual baseline?"}
{"t":"step","id":"email-in","kind":"trigger","label":"Invoice email received","product":"eventbridge","runs":"fc","untrusted":true,"effect":"read","why":"Inbound email webhook via EventBridge into Function Compute"}
{"t":"step","id":"guard","kind":"guard","label":"Screen email content","product":"ai-guardrails","runs":"fc","effect":"read","untrusted":true,"why":"Block prompt injection or malicious payloads before agent processes them"}
