{"t":"step","id":"erp-api-tool","kind":"tool","label":"Query and post ERP","task":"retrieve","tool":"mcp","on":"match-agent","effect":"write","approval":"required","private":true,"why":"Read POs and GRs, write approved invoices; needs approval for ERP writes"}
{"t":"step","id":"human-review","kind":"human","label":"Approve invoice posting","task":"approve","subject":"match-agent","runs":"cloudflow","approval":"required","why":"Posting to ERP is a financial commitment requiring human approval"}
{"t":"step","id":"posted","kind":"end","label":"Invoice posted to ERP","runs":"customer","why":"Successful completion state"}
{"t":"step","id":"rejected","kind":"end","label":"Invoice rejected","runs":"customer","why":"Terminal state when reviewer rejects the invoice"}
{"t":"link","id":"in-guard","from":"email-in","to":"guard","kind":"next","label":"email arrived"}
{"t":"link","id":"guard-agent","from":"guard","to":"match-agent","kind":"next","label":"safe content"}
{"t":"link","id":"agent-review","from":"match-agent","to":"human-review","kind":"next","label":"match complete, ready for approval"}
{"t":"link","id":"review-posted","from":"human-review","to":"posted","kind":"branch","outcome":"approve","label":"approved"}
{"t":"link","id":"review-rejected","from":"human-review","to":"rejected","kind":"branch","outcome":"reject","label":"rejected"}
{"t":"link","id":"review-edit","from":"human-review","to":"match-agent","kind":"branch","outcome":"edit","label":"needs revision","max":3}
