{"t":"say","text":"Single agent with attached tools for ingestion, clustering, drafting, and PR approval before publishing replies."}
{"t":"assume","id":"source","text":"Reviews arrive via webhook or API poll into EventBridge"}
{"t":"assume","id":"pr-target","text":"PR targets a GitHub or GitLab repository via API"}
{"t":"assume","id":"volume","text":"Moderate daily review volume fits single agent turns"}
{"t":"ask","id":"q-vol","text":"How many marketplace reviews do you ingest per day?","options":["Under 100","100 to 1000","Over 1000"]}
{"t":"ask","id":"q-base","text":"What defines success today, and what is your current baseline response time?","options":["Faster replies","Better tone","Fewer escalations"]}
{"t":"step","id":"ingest","kind":"trigger","label":"Ingest marketplace reviews","product":"eventbridge","runs":"fc","untrusted":true,"effect":"read","why":"Entry point receiving raw review payloads from the marketplace"}
{"t":"step","id":"guard","kind":"guard","label":"Screen review content","product":"ai-guardrails","runs":"fc","after":"ingest","why":"Sanitize untrusted inbound text before any model processing"}
{"t":"step","id":"review-agent","kind":"agent","label":"Process and cluster reviews","task":"plan","ai":"qwen3.8-max","runs":"agentrun","turns":10,"after":"guard","why":"Orchestrates extraction, theme clustering, sentiment check and draft generation"}
{"t":"step","id":"extract-tool","kind":"tool","label":"Extract review fields","task":"extract","tool":"code_interpreter","on":"review-agent","runs":"agentrun","effect":"read","why":"Parse raw JSON into structured review objects for downstream steps"}
{"t":"step","id":"cluster-tool","kind":"tool","label":"Cluster by theme","task":"generate","tool":"code_interpreter","on":"review-agent","runs":"agentrun","effect":"write","why":"Group extracted reviews into thematic clusters using embedding similarity"}
{"t":"step","id":"sentiment-tool","kind":"tool","label":"Check sentiment","task":"classify","tool":"code_interpreter","on":"review-agent","runs":"agentrun","effect":"read","why":"Identify negative reviews that require drafted replies"}
{"t":"step","id":"draft-tool","kind":"tool","label":"Draft negative replies","task":"generate","tool":"code_interpreter","on":"review-agent","runs":"agentrun","effect":"write","why":"Generate professional reply drafts only for negative clustered reviews"}
{"t":"step","id":"create-pr","kind":"act","label":"Create PR for approval","effect":"publish","product":"third-party-api","runs":"agentrun","after":"review-agent","approval":"required","why":"Push drafted replies as a pull request for human PR review"}
{"t":"step","id":"pr-approve","kind":"human","label":"Approve PR replies","task":"approve","subject":"create-pr","runs":"cloudflow","after":"create-pr","why":"Human gate ensuring no reply is posted without explicit PR merge approval"}
{"t":"step","id":"post-reply","kind":"act","label":"Post approved replies","effect":"publish","product":"third-party-api","runs":"agentrun","after":"pr-approve","approval":"required","why":"Publish merged replies back to the marketplace via API"}
{"t":"step","id":"posted","kind":"end","label":"Replies posted","runs":"customer","after":"post-reply","why":"Terminal state after successful publication"}
{"t":"step","id":"rejected","kind":"end","label":"PR rejected or timed out","runs":"customer","after":"pr-approve","why":"Terminal state when approval is denied or expires"}
{"t":"link","id":"ingest-guard","from":"ingest","to":"guard","kind":"next","label":"Review received"}
{"t":"link","id":"guard-agent","from":"guard","to":"review-agent","kind":"next","label":"Content safe"}
{"t":"link","id":"agent-pr","from":"review-agent","to":"create-pr","kind":"next","label":"Drafts ready"}
{"t":"link","id":"pr-human","from":"create-pr","to":"pr-approve","kind":"next","label":"PR created"}
{"t":"link","id":"approve-post","from":"pr-approve","to":"post-reply","kind":"branch","outcome":"approve","label":"PR merged"}
{"t":"link","id":"approve-reject","from":"pr-approve","to":"rejected","kind":"branch","outcome":"reject","label":"PR closed"}
{"t":"link","id":"approve-timeout","from":"pr-approve","to":"rejected","kind":"branch","outcome":"timeout","label":"Approval expired"}
{"t":"link","id":"post-done","from":"post-reply","to":"posted","kind":"next","label":"Published"}
{"t":"done","summary":"Single agent ingests untrusted reviews, clusters themes, drafts replies for negatives, and gates posting behind PR approval via CloudFlow."}

